/**
 * 导出示例：把流程图导出为 Minecraft 数据包友好的 .mcfunction（演示
 * “插件私有格式/导出 MC 插件”场景）——每个节点一行 tellraw 消息。
 */
export default {
  id: 'demo.mc-exporter',
  name: 'MC 函数导出（示例）',
  version: '1.0.0',
  description: '将图表导出为 .mcfunction（每节点一条 tellraw）',
  permissions: ['export:format'],
  export: {
    id: 'mcfunction',
    label: 'MC 函数（.mcfunction）',
    run({ code }) {
      const nodes = [...code.matchAll(/^\s*([A-Za-z0-9_]+)\s*(?:-->|---)\s*([A-Za-z0-9_]+)/gm)]
        .flatMap((m) => [m[1], m[2]]);
      const unique = [...new Set(nodes)];
      const lines = [
        '# Generated by flow-editor plugin demo.mc-exporter',
        ...unique.map(
          (n) => `tellraw @a {"text":"[diagram] node: ${n}","color":"aqua"}`
        )
      ];
      return { filename: 'diagram.mcfunction', mime: 'text/plain', text: lines.join('\n') + '\n' };
    }
  }
};
